fn code() -> Vec<u8> {
    let mut d = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    loop {
        let p = d.join("original").join("neutral_3.text.bin");
        if p.exists() { return std::fs::read(p).unwrap(); }
        assert!(d.pop(), "original/neutral_3.text.bin not found above the crate");
    }
}

fn run(name: &str, f: impl FnMut(&mut neutral_world::World, &neutral_world::WCase) -> Vec<u128>) {
    let mut f = f;
    let dir = std::env::var("VEC_DIR").map(PathBuf::from).unwrap_or_else(|_| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..").join("vectors"));
    let c = code();
    let (mut compared, mut failed, mut rfaults) = (0usize, 0usize, 0usize);
    let mut mism: Vec<String> = Vec::new();
    let only = std::env::var("DBG_SET").ok();
    let min: usize = std::env::var("WORLD_MIN").ok().and_then(|v| v.parse().ok()).unwrap_or(900);
    let mut sets: Vec<String> = vec![String::new()];
    if let Ok(rd) = std::fs::read_dir(&dir) {
        let pre = format!("{}.world", name);
        let mut nums: Vec<u32> = rd.filter_map(|e| e.ok()).filter_map(|e| { let f = e.file_name().to_string_lossy().to_string(); if f.starts_with(&pre) && f.ends_with(".vec") { f[pre.len()..f.len() - 4].parse::<u32>().ok() } else { None } }).collect();
        nums.sort();
        for n in nums { if n >= 2 { sets.push(n.to_string()); } }
    }
    for set in sets.iter().map(|s| s.as_str()) {
        if let Some(o) = &only { if o != set { continue; } }
        let path = dir.join(format!("{}.world{}.vec", name, set));
        if !path.exists() { assert!(!set.is_empty(), "missing vector file {}", path.display()); continue; }
        lift_7::pin::load_sidecar(&PathBuf::from(format!("{}.pins", path.display())));
        let mut vf = load(&path).unwrap();
        if let Ok(s) = std::env::var("DBG_CASE") { if let Ok(i) = s.parse::<usize>() { vf.cases = vec![vf.cases[i].clone()]; } }
        let rep = check(&vf, Some(&c), &mut f);
        println!("WORLD {} total={} compared={} skipped={} failed={} rust_faults={} set={}", rep.name, rep.total, rep.compared, rep.skipped, rep.failed, rep.rust_faults, if set.is_empty() { "1" } else { set });
        for m in rep.mismatches.iter().take(3) { println!("MISMATCH {} {}", name, m.chars().take(400).collect::<String>()); }
        compared += rep.compared; failed += rep.failed; rfaults += rep.rust_faults;
        mism.extend(rep.mismatches.iter().take(3).cloned());
    }
    assert!(failed == 0 && rfaults == 0 && compared >= min, "{}: {} failed, {} rust faults, {} compared (need {})\n{}", name, failed, rfaults, compared, min, mism.join("\n"));
}

